use kimo_core::{color::ocio,effects::Frame,model::Project};
#[test]fn ocio_domain_rejection(){let mut p=Project::default();let f=Frame{w:1,h:1,d:vec![0.18,0.18,0.18,1.]};assert!(ocio::reference(&p,&f,"sdr").is_err());p.color_pipeline.enabled=true;p.color_pipeline.working_gamut=0;assert!(ocio::reference(&p,&f,"sdr").is_err());p.color_pipeline.working_gamut=3;assert!(ocio::reference(&p,&f,"garbage").is_err());}
#[test]fn ocio_optional_real_processor(){if std::env::var("KIMO_TEST_OCIO").is_err(){return}let mut p=Project::default();p.color_pipeline.enabled=true;p.color_pipeline.working_gamut=3;let f=Frame{w:2,h:1,d:vec![-0.25,1.25,4.,0.5,0.18,0.18,0.18,1.]};let q=ocio::reference(&p,&f,"sdr").unwrap();assert!(q.d.iter().all(|v|v.is_finite()));assert_eq!(q.d[3],0.5);}
#[test]fn persistent_matches_oneshot(){if std::env::var("KIMO_TEST_OCIO").is_err(){return}let mut p=Project::default();p.color_pipeline.enabled=true;p.color_pipeline.working_gamut=3;let f=Frame{w:32,h:16,d:(0..512).flat_map(|i|[i as f32/100.,0.18,0.4,0.5]).collect()};for mode in ["sdr","pq2020"]{let expected=ocio::reference(&p,&f,mode).unwrap();let mut processor=ocio::Processor::new(&p,32,16,mode).unwrap();for _ in 0..10{assert_eq!(processor.apply(&f).unwrap().d,expected.d)}let bad=Frame{w:32,h:16,d:vec![f32::NAN;2048]};assert!(processor.apply(&bad).is_err());assert_eq!(processor.apply(&f).unwrap().d,expected.d);drop(processor);}}

#[test]fn reference_video_rejects_invalid(){let mut p=Project::default();assert!(ocio::export_sdr_video(&p,"/tmp/x.mov",18).is_err());assert!(ocio::export_sdr_video(&p,"/tmp/x.mp4",52).is_err());p.width=1;assert!(ocio::export_sdr_video(&p,"/tmp/x.mp4",18).is_err());p.width=2;p.fps=f64::NAN;assert!(ocio::export_sdr_video(&p,"/tmp/x.mp4",18).is_err());}
#[test]fn reference_comparison_domain(){let mut p=Project::default();let f=Frame{w:1,h:1,d:vec![0.18,0.18,0.18,1.]};assert!(ocio::compare_sdr(&p,&f).is_err());p.color_pipeline.enabled=true;p.color_pipeline.output_transfer=8;assert!(ocio::compare_sdr(&p,&f).is_err());}
#[test]fn actual_reference_comparison_finite(){if std::env::var("KIMO_TEST_OCIO").is_err(){return}let mut p=Project::default();p.color_pipeline.enabled=true;let f=Frame{w:2,h:1,d:vec![0.18,0.18,0.18,1.,4.,1.,-0.1,0.5]};let v=ocio::compare_sdr(&p,&f).unwrap();assert_eq!(v["visible_pixels"],2);assert_eq!(v["configured_outside_0_1_pixels"],1);assert!(v["rmse_rgb"].as_array().unwrap().iter().all(|v|v.as_f64().unwrap().is_finite()));}
#[test]fn reference_alpha_and_shape_preflight(){let mut p=Project::default();p.color_pipeline.enabled=true;for f in [Frame{w:1,h:1,d:vec![0.1,0.2,0.3,-0.1]},Frame{w:1,h:1,d:vec![0.1,0.2,0.3,1.01]},Frame{w:1,h:1,d:vec![0.;3]}]{assert!(ocio::reference(&p,&f,"sdr").err().unwrap().contains("before processor spawn"));}}
